from __future__ import absolute_import
from selenium.webdriver.common.by import By
from taf.selenium.sbts_fsm3.pages.v23r1.modals import LoadRamlProfileModal
from taf.selenium.sbts_fsm3.pages import v22r2


class NetconfRadioManagementPage(v22r2.NetconfRadioManagementPage):

    def __init__(self, driver):
        super(NetconfRadioManagementPage, self).__init__(driver)
        self._view_panel = NetconfRadioManagementPageViewPanel(driver)


class NetconfRadioManagementPageViewPanel(v22r2.configuration.NetconfRadioManagementPageViewPanel):

    def __init__(self, driver):
        super(NetconfRadioManagementPageViewPanel, self).__init__(driver)

    def load_netconf_profile(self, file_path, apply_for_warning, timeout=60):
        self.click_enabled_element((By.XPATH, self._LOAD_PROFILE_BUTTON), timeout)
        load_raml_profile_modal = LoadRamlProfileModal(self.driver)
        load_raml_profile_modal.wait_until_load_raml_profile_modal_appear(timeout)
        load_raml_profile_modal.upload_profile(file_path, timeout)
        status = load_raml_profile_modal.apply(apply_for_warning, timeout)
        return status
